text:
```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEFA"); // Sky blue
  brush.fillBleed(0.3);
  brush.beginShape();
  brush.vertex(0, 0);     // Top left
  brush.vertex(400, 0);   // Top right
  brush.vertex(400, 400); // Bottom right
  brush.vertex(0, 400);   // Bottom left
  brush.endShape(true);

  // Green hills
  brush.fill("#336600"); // Green
  brush.fillBleed(0.5);
  brush.beginShape();
  brush.vertex(0, 200);  // Top left hill
  brush.vertex(400, 200); // Top right hill
  brush.vertex(400, 300); // Bottom right hill
  brush.vertex(0, 300);   // Bottom left hill
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700"); // Golden yellow
  brush.fillBleed(0.7);
  brush.beginShape();
  brush.vertex(200, 100); // Sun position
  brush.vertex(220, 80);  // Sun disk
  brush.vertex(240, 100); // Sun disk
  brush.vertex(220, 120); // Sun disk
  brush.endShape(true);
}
```

